html:
{#-
	Manav Modern Quotation Head: print format of Quotation Head (the old quotations, and the
	quotations made in that doctype) in the modern black and white layout. It is the default
	print format of Quotation Head; the earlier layout "Manav Quotation" stays selectable.

	Working: the layout itself is the file
	manav/templates/print_formats/manav_modern_quotation_body.html, which is shared with the
	print format of ERPNext's Quotation (Manav Modern Quotation). This print format only gathers
	the values of a Quotation Head into the variable `q`, in the shape that file describes, and
	then includes it:
	- every row of Items is a machine; its options are the rows of Options whose Main Item Code
	  is the machine's code; its specification lines are the rows of Specifications with its
	  item code (a row marked Bold starts with "!"); its picture is the Image of the ERPNext Item
	  of the same code, as Quotation Head has no picture field;
	- amounts are plain numbers with the currency as typed in the old system (RS, US$) in front;
	- the taxes are the three tax amounts of the old system, named as on the quotations made
	  since GST (CGST, SGST, IGST), and the freight;
	- the terms rows become one table, one term to a row, as the Terms templates are;
	- the names of the signing employee and the sales engineer are read from Employee Master by
	  the codes on the quotation, so the old quotations (which hold only the codes) print them;
	- Quotation Head has no company and no office address: the company name is fixed here.

	An old quotation was loaded without its item rows. It then prints no specification box and
	no line table: header, totals as stored, terms and signature.

	Created: 2026-10-13, when the user asked for the new layout on all quotations.

	CHANGE NOTE
	Date: 2026-10-14
	Change: The picture of each machine (from the ERPNext Item) is passed on to the shared layout.
	Reason: The user asked for the image of the item on the quotation.

	CHANGE NOTE
	Date: 2026-10-14
	Change: A machine without Specifications rows prints the Specifications of the ERPNext Item
	of the same code.
	Reason: The user keeps the specifications on the Item; before, Quotation Head printed only
	its own rows.
-#}
{%- set currency = doc.currency or "" -%}
{%- macro money(value) -%}{{ (currency ~ " " ~ frappe.utils.fmt_money(value or 0, 2)) | trim }}{%- endmacro -%}
{%- macro count(value) -%}{{ "%g" | format(value or 0) }}{%- endmacro -%}
{%- set signer = frappe.db.get_value("Employee Master", doc.signature_one_code, ["employee_name", "designation"], as_dict=True) if doc.signature_one_code else None -%}
{%- set engineer = doc.sales_engineer_name or (frappe.db.get_value("Employee Master", doc.signature_two_code, "employee_name") if doc.signature_two_code else None) or doc.signature_two_code -%}
{#- old quotations have no Haas Cust ID of their own; it is then read from the customer -#}
{%- set cust_id = doc.haas_customer_id or (frappe.db.get_value("Customer", doc.customer, "custom_haas_customer_id") if doc.customer else None) -%}
{%- set items = doc.get("items") or [] -%}
{%- set item_codes = items | map(attribute="item_code") | list -%}
{%- set sub_items = doc.get("sub_items") or [] -%}

{%- set address_lines = [doc.address_1, doc.address_2, doc.address_3, ((doc.city or "") ~ " " ~ (doc.pin or "")) | trim, doc.state] | select | list -%}
{%- set q = {
	"company": "Manav Marketing Pvt. Ltd.",
	"date": frappe.utils.getdate(doc.quotation_date) if doc.quotation_date else None,
	"number": doc.name,
	"customer_name": doc.customer_name or doc.customer,
	"address": address_lines | join("<br>"),
	"attn": ((doc.contact_person or "") ~ ((", " ~ doc.designation) if doc.contact_person and doc.designation else "")) | trim,
	"phone": "",
	"issuer_address": "",
	"refs": [],
	"notes": [doc.message_line_1, doc.message_line_2] | select | list,
	"machines": [],
	"loose_options": [],
	"subtotal": money(doc.quotation_amount) | trim,
	"taxes": [],
	"grand_total": money(doc.final_amount) | trim,
	"payment": [],
	"terms": "",
	"signer": doc.signed_by_name or (signer.employee_name if signer else doc.signature_one_code),
	"designation": signer.designation if signer else None,
} -%}

{#- the four reference fields of the old quotation header; all are given, filled or not -#}
{%- set _ = q.refs.extend([
	["Ref. No.", doc.your_reference],
	["Ref Dt.", frappe.utils.getdate(doc.your_reference_date).strftime("%d/%m/%y") if doc.your_reference_date else ""],
	["Sales Engg.", engineer],
	["Cust ID", cust_id],
]) -%}

{#- machines with their specification lines and options, then the options without their machine -#}
{%- for item in items -%}
	{%- set spec_lines = [] -%}
	{%- for spec in (doc.get("specifications") or []) | selectattr("item_code", "equalto", item.item_code) -%}
		{%- if spec.specification -%}{%- set _ = spec_lines.append(("!" if spec.highlight else "") ~ spec.specification) -%}{%- endif -%}
	{%- endfor -%}
	{#- without Specifications rows of its own, the Specifications of the ERPNext Item of that code -#}
	{%- if not spec_lines and item.item_code -%}
		{%- set item_specs = frappe.db.get_value("Item", item.item_code, "custom_specifications") -%}
		{%- if item_specs -%}{%- set _ = spec_lines.append(item_specs) -%}{%- endif -%}
	{%- endif -%}
	{%- set options = [] -%}
	{%- for option in sub_items | selectattr("main_item_code", "equalto", item.item_code) -%}
		{%- set _ = options.append({"code": option.sub_item_code, "name": "", "description": option.item_description, "rate": money(option.rate) | trim, "qty": count(option.qty) | trim, "amount": money(option.amount) | trim}) -%}
	{%- endfor -%}
	{#- Quotation Head has no picture of its own; the ERPNext Item of the same code has one -#}
	{%- set image = frappe.db.get_value("Item", item.item_code, "image") if item.item_code else None -%}
	{%- set _ = q.machines.append({"code": item.item_code, "name": "", "image": image, "spec_text": spec_lines | join("\n"), "description": item.item_description, "rate": money(item.rate) | trim, "qty": count(item.qty) | trim, "amount": money(item.amount) | trim, "options": options}) -%}
{%- endfor -%}
{%- for option in sub_items | rejectattr("main_item_code", "in", item_codes) -%}
	{%- set _ = q.loose_options.append({"code": option.sub_item_code, "name": "", "description": option.item_description, "rate": money(option.rate) | trim, "qty": count(option.qty) | trim, "amount": money(option.amount) | trim}) -%}
{%- endfor -%}

{#- the tax amounts and the freight, each only when it is not zero -#}
{%- for label, percent, amount in [["Sales Tax / CGST", doc.sales_tax_percent, doc.sales_tax_amount], ["SGST", doc.sc_on_sales_tax_percent, doc.sc_on_sales_tax_amount], ["IGST", doc.sc_on_taxable_percent, doc.sc_on_taxable_amount]] -%}
	{%- if frappe.utils.flt(amount) -%}
		{%- set _ = q.taxes.append([label ~ ((" @ " ~ ("%g" | format(percent)) ~ "%") if frappe.utils.flt(percent) else ""), money(amount) | trim]) -%}
	{%- endif -%}
{%- endfor -%}
{%- if frappe.utils.flt(doc.freight) -%}{%- set _ = q.taxes.append(["Freight", money(doc.freight) | trim]) -%}{%- endif -%}

{#- The terms as one table. A second line of the same term (Sr No above 1 and no heading)
    continues without a number; the shared layout keeps such a row with the term above it. -#}
{%- set term_rows = [] -%}
{%- for term in doc.get("terms") or [] -%}
	{%- set number = term.term_type if term.term_desc or term.sr_no in (None, 0, 1) else "" -%}
	{%- set _ = term_rows.append('<tr><td style="width: 5%;">' ~ (number or "") ~ '</td><td style="width: 32%;">' ~ (term.term_desc or "") ~ "</td><td>" ~ ((term.description or "") | replace("\n", "<br>")) ~ "</td></tr>") -%}
{%- endfor -%}
{%- if term_rows -%}{%- set _ = q.update({"terms": "<table>" ~ (term_rows | join("")) ~ "</table>"}) -%}{%- endif -%}

{% include "manav/templates/print_formats/manav_modern_quotation_body.html" %}
